#!/usr/bin/env node

'use strict';

/**
 * Builds `pages/translation-status-data/status.js` from the metadata in the
 * content pages and their `translations.js` files.
 *
 * The generated file is what `pages/translation-status.en.html` renders. Run
 * `npm run build:translation-status` after changing content or translation
 * metadata.
 */

const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const repoRoot = path.resolve(__dirname, '..');
const outputFile = path.join(repoRoot, 'pages', 'translation-status-data', 'status.js');

const contentRoots = [
  'articles',
  'questions',
  'tutorials',
  'getting-started',
  'quicktips',
  'pages',
  'nav',
  'techniques',
];

const typeLabels = {
  articles: 'Article',
  questions: 'Question',
  tutorials: 'Tutorial',
  'getting-started': 'Getting started',
  quicktips: 'Quick tip',
  pages: 'Page',
  nav: 'Site page',
  techniques: 'Technique',
};

function main() {
  const pages = [];

  for (const [id, entries] of collectEntries()) {
    const page = buildPage(id, entries);
    if (page) {
      pages.push(page);
    }
  }

  pages.sort((left, right) => left.id.localeCompare(right.id));

  const payload = {
    generated: formatToday(),
    pages,
  };

  const header = [
    '// Generated by scripts/build-translation-status.js on ' + payload.generated + '.',
    '// Do not edit this file by hand. Run `npm run build:translation-status` to refresh it.',
    '',
  ].join('\n');
  const output = header + 'var translationStatus = ' + JSON.stringify(payload, null, 2) + ';\n';

  if (process.argv.includes('--check')) {
    checkUpToDate(payload);
    return;
  }

  fs.writeFileSync(outputFile, output);
  console.log('Wrote ' + toPosix(path.relative(repoRoot, outputFile)) + ' (' + pages.length + ' pages).');
}

/**
 * Verifies that the committed data matches the content, ignoring the generation
 * date so that the check doesn't fail at midnight.
 */
function checkUpToDate(payload) {
  if (!fs.existsSync(outputFile)) {
    console.error('Missing ' + toPosix(path.relative(repoRoot, outputFile)) + '. Run `npm run build:translation-status`.');
    process.exitCode = 1;
    return;
  }

  const sandbox = {};
  vm.runInNewContext(fs.readFileSync(outputFile, 'utf8'), sandbox, { timeout: 1000 });
  const current = sandbox.translationStatus;

  if (!current || JSON.stringify(current.pages) !== JSON.stringify(payload.pages)) {
    console.error(
      toPosix(path.relative(repoRoot, outputFile)) +
        ' is out of date. Run `npm run build:translation-status`.'
    );
    process.exitCode = 1;
    return;
  }

  console.log(toPosix(path.relative(repoRoot, outputFile)) + ' is up to date.');
}

/**
 * Walks the content roots and groups content pages by `directory + filename stem`,
 * so that `index.en.html` and `index.zh-hans.html` end up together.
 */
function collectEntries() {
  const groups = new Map();

  for (const root of contentRoots) {
    walk(path.join(repoRoot, root), root, groups);
  }

  return groups;
}

function walk(absoluteDir, root, groups) {
  if (!fs.existsSync(absoluteDir)) {
    return;
  }

  for (const entry of fs.readdirSync(absoluteDir, { withFileTypes: true })) {
    if (entry.name.startsWith('.')) {
      continue;
    }

    const absolutePath = path.join(absoluteDir, entry.name);

    if (entry.isDirectory()) {
      // Content pages live directly in the content directories; `*-data`
      // directories hold translations metadata, styles, and images.
      if (!entry.name.endsWith('-data')) {
        walk(absolutePath, root, groups);
      }
      continue;
    }

    if (!/\.html?$/i.test(entry.name)) {
      continue;
    }

    const source = fs.readFileSync(absolutePath, 'utf8');
    const metadata = readMetadata(source);
    if (!metadata) {
      continue;
    }

    const fileName = path.basename(absolutePath);
    const { stem, language } = parsePageFilename(fileName);
    const relativePath = toPosix(path.relative(repoRoot, absolutePath));
    const directory = toPosix(path.dirname(relativePath));
    const id = directory + '/' + stem;

    if (!groups.has(id)) {
      groups.set(id, []);
    }

    groups.get(id).push({
      root,
      id,
      stem,
      directory,
      relativePath,
      language: language || 'en',
      metadata,
      source,
    });
  }
}

/**
 * Reads the `var f = {}` metadata block of a content page. Example fragments
 * and other HTML files in `*-data` directories don't have one, so they are
 * skipped.
 */
function readMetadata(source) {
  const match = source.match(/<script\b[^>]*>([\s\S]*?\bvar\s+f\s*=\s*\{\s*\}[\s\S]*?)<\/script>/i);
  if (!match) {
    return null;
  }

  const sandbox = { f: {} };
  try {
    vm.runInNewContext(match[1], sandbox, { timeout: 1000 });
  } catch (error) {
    console.warn('Could not read page metadata: ' + error.message);
    return null;
  }

  if (!sandbox.f || typeof sandbox.f !== 'object' || typeof sandbox.f.filename !== 'string') {
    return null;
  }

  return sandbox.f;
}

function parsePageFilename(fileName) {
  const htmlStem = fileName.replace(/\.html?$/i, '');
  const match = htmlStem.match(/^(.*)\.([a-z]{2,3}(?:-[a-z0-9]{2,8})*)$/i);
  if (!match) {
    return { stem: htmlStem, language: null };
  }
  return { stem: match[1], language: match[2].toLowerCase() };
}

function buildPage(id, entries) {
  const english = entries.find((entry) => entry.language === 'en');
  if (!english) {
    console.warn('No English version found for ' + id + '; skipping.');
    return null;
  }

  const files = new Map();
  for (const entry of entries) {
    if (entry.language === 'en') {
      continue;
    }
    files.set(entry.language, {
      href: relativeHref(entry.relativePath),
      updated: dateOf(entry.metadata.thisVersion),
    });
  }

  const translations = readTranslations(english);
  const declaredVersions = translations && Array.isArray(translations.versions)
    ? translations.versions.map(String)
    : [...files.keys()];

  // Only claim a translation exists when there is a file for it.
  const versions = declaredVersions.filter((language) => files.has(language));
  if (!versions.includes('en')) {
    versions.unshift('en');
  }

  const translated = {};
  for (const language of versions) {
    if (language !== 'en' && files.has(language)) {
      translated[language] = files.get(language);
    }
  }

  const archived = {};
  for (const language of arrayOf(translations && translations.unlinkedtranslations)) {
    if (files.has(language) && !translated[language]) {
      archived[language] = files.get(language);
    }
  }

  const outOfDate = arrayOf(translations && translations.outofdatetranslations).filter(
    (language) => Boolean(translated[language])
  );

  return {
    id,
    title: pageTitle(english.source),
    type: typeLabels[english.root] || 'Page',
    href: relativeHref(english.relativePath),
    status: english.metadata.status || 'unknown',
    updated: dateOf(english.metadata.lastSubstUpdate) || dateOf(english.metadata.thisVersion),
    translated,
    archived,
    outOfDate,
  };
}

/**
 * Finds the `translations.js` file that the English page loads. Falls back to
 * the two naming patterns used in the repository when the page doesn't load one.
 */
function readTranslations(english) {
  const candidates = [];

  for (const match of english.source.matchAll(/<script\b[^>]*\bsrc\s*=\s*["']([^"']*translations\.js)["'][^>]*>/gi)) {
    const resolved = path.posix.normalize(path.posix.join(english.directory, match[1]));
    candidates.push(resolved);
  }

  candidates.push(path.posix.join(english.directory, english.stem + '-data', 'translations.js'));
  candidates.push(
    path.posix.join(english.directory, path.posix.basename(english.directory) + '-data', 'translations.js')
  );

  for (const candidate of new Set(candidates)) {
    const absolutePath = path.join(repoRoot, candidate);
    if (!fs.existsSync(absolutePath)) {
      continue;
    }

    const sandbox = { trans: {} };
    try {
      vm.runInNewContext(fs.readFileSync(absolutePath, 'utf8'), sandbox, { timeout: 1000 });
    } catch (error) {
      console.warn('Could not read ' + candidate + ': ' + error.message);
      return null;
    }

    return sandbox.trans && typeof sandbox.trans === 'object' ? sandbox.trans : null;
  }

  return null;
}

function pageTitle(source) {
  const heading = source.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i);
  const title = source.match(/<title>([\s\S]*?)<\/title>/i);
  const raw = heading ? heading[1] : title ? title[1] : '';
  return decodeEntities(raw.replace(/<[^>]+>/g, '')).replace(/\s+/g, ' ').trim();
}

function decodeEntities(text) {
  const named = {
    amp: '&',
    lt: '<',
    gt: '>',
    quot: '"',
    apos: "'",
    nbsp: '\u00a0',
  };

  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z][a-z0-9]*);/gi, (entity, body) => {
    if (body[0] === '#') {
      const isHex = body[1] === 'x' || body[1] === 'X';
      const code = Number.parseInt(isHex ? body.slice(2) : body.slice(1), isHex ? 16 : 10);
      return Number.isFinite(code) ? String.fromCodePoint(code) : entity;
    }

    const replacement = named[body.toLowerCase()];
    return replacement === undefined ? entity : replacement;
  });
}

function relativeHref(relativePath) {
  return '../' + relativePath;
}

function dateOf(value) {
  return value && typeof value.date === 'string' ? value.date : null;
}

function arrayOf(value) {
  return Array.isArray(value) ? value.map(String) : [];
}

function formatToday() {
  const now = new Date();
  return [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, '0'),
    String(now.getDate()).padStart(2, '0'),
  ].join('-');
}

function toPosix(filePath) {
  return filePath.split(path.sep).join('/');
}

main();
